"OLAYLAR_EK5:1400-08-01:0":{"b": ["تيمور سيواس له ځمکې سره برابر کړ", "f4d79de6"], "d": ["تيمور، چې د آق قوينلو قره يولوک عثمان بېګ او د ارزنجان امير مطهرتن په لارښوونه پر سيواس روان شو، ښار اتلس ورځې محاصره کړ او وروسته له دې چې په دې وعده يې تسليم کړ چې د هېچا وينه به ونه بهېږي، لويه قتل عام وکړ؛ مدافعين يې په خندقونو کې ډک کړل او ژوندي يې پر خاوره پټ کړل. د ښار مهم آثار، په سر کې دېوالونه، ويجاړ شول او سيواس د نفوس له پلوه ړنګ شو. دا د انقرې له جګړې دوه کاله مخکې پر عثماني خاورو د تيمور لومړۍ لويه ضربه ده.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["يلديرم بايزيد ارزنجان او کماخ بېرته ونيول", "7047ca08"], "d": ["يلديرم بايزيد، چې د تيمور د سوريې لښکرکشۍ ته وتلو څخه يې ګټه واخيسته، له هغه ارزنجاني امير مطهرتن څخه چې تيمور ته تابع و، ارزنجان او کماخ واخيستل. که څه هم هغه د سيواس په ويجاړۍ کې لاسوهنه نه وه کړې، دا اقدام د ختيځې اناطولې په تيموري نفوذ سيمه مستقيمه ننګونه وه. له هغه وروسته د دوو واکمنو اړيکې داسې شوې چې رغول يې ناممکن شول.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["له تبريزه د تيمور الټيماتوم — څلور شرطونه", "3e1ac50e"], "d": ["تيمور له تبريزه د لېږل شوي استازي له لارې څلور شرطونه اعلان کړل: مطهرتن ته د کماخ بېرته ورکول، د اناطولې له بېګانو څخه اخيستل شويو ځمکو خاوندانو ته بېرته ورکول، د عثماني يوه شهزاده د يرغمل په توګه لېږل او خولۍ (کلاه) او کمربند د تابعيت نښې په توګه منل، او د قره يوسف سپارل. بايزيد له دې هېڅ يو ونه منل؛ د دولتي مشرانو د ټينګار او د مطهرتن د منځګړتوب سره سره خبرې ړنګې شوې. تيمور هوډ کړی و چې چين لښکرکشۍ ته له وتلو مخکې د اناطولې مسئله پرېکنده وتړي.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["ساروخان اوغللاري بيا تاسيس شول — مانيسا له عثمانيانو ووته", "ac747b05"], "d": ["د انقرې له ماتې درې اونۍ وروسته، د تيمور په ملاتړ، اورخان بېګ د بېګلک مشر شو او د ساروخان ولايت بيا خپلواک شو. هغه سيمه چې مرکز يې مانيسا و، د ۱۳۹۰ کال د عثماني الحاق له دولسو کلونو وروسته له نقشې ووتله. دا د تيمور د بېګلکونو د بيا ژوندي کولو د سياست له لومړنيو تطبيقونو څخه دی چې نېټه يې په يقين معلومه ده.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["امير سليمان له دولتي خزانې سره روم ايلي ته وتښتېد", "0a2b7363"], "d": ["امير سليمان، چې په بورسه کې دولتي خزانه، آرشيفونه، کورنۍ او وروڼه يې له ځانه سره واخيستل، له ګيمليک څخه په کښتۍ ګوزلجه حصار (اناطولو حصار) ته تېر شو، له هغه ځايه ګليبولي ته ورسېد او په ادرنه کې يې خپله واکمني اعلان کړه. روم ايلي ته د دولتي آرشيف او خزانې لېږد د يوه نسل لپاره بالکان ته د عثماني د ثقل مرکز د اوښتلو پيل دی. په نقشه کې روم ايلي له دې نېټې وروسته د امير سليمان په خپل رنګ ښودل کېږي.", "393aa053"]},
